// =====================================================================
// rx_fft_frontend_rand_tb.sv
// ---------------------------------------------------------------------
// ROBUST multi-vector self-checking TB for rx_fft_frontend.
//
//  * Loads golden/rx_fft_rand/slots_in.hex (N_VEC*4032 lines) and
//    golden/rx_fft_rand/fft_out.hex (N_VEC*3072 lines), generated by
//    scripts/gen_rx_fft_frontend_random.py (N random data slots + edge
//    cases: PAPR/full-scale, single-tone, all-zero, max-mag impulse).
//  * For EACH vector v: streams its 4032-sample slot into the DUT one
//    complex sample/clock with pseudo-random s_valid gaps AND m_ready
//    stalls (AXI-S tready exercised both directions), collects the
//    12*256=3072 freq bins, compares to that vector's golden block.
//  * Because the real xfft uses block-floating-point + truncation, a
//    few-LSB error vs the integer-domain golden is expected. PASS = every
//    bin of every vector within TOL LSB on BOTH I and Q. Reports the
//    GLOBAL max abs LSB error and WHICH vector/symbol/bin caused it.
//
//  Vectors are streamed back-to-back through the SAME DUT instance (no
//  reset between them) so inter-slot pipelining / buffer reuse is also
//  exercised.  The DUT's slot FSM free-runs and wraps every 4032 input
//  beats, so vector boundaries align naturally.
//
//  N_VEC is read from line 1 of golden/rx_fft_rand/meta.txt at elaboration
//  via the +N_VEC plusarg (passed by the runner); defaults to 28.
// =====================================================================
`timescale 1ns/1ps
`default_nettype none

module rx_fft_frontend_rand_tb;

    localparam integer NSC      = 256;
    localparam integer CP_LEN   = 32;
    localparam integer NUM_SYN  = 2;
    localparam integer NUM_DATA = 12;
    localparam integer SLOT_LEN = (NUM_SYN + NUM_DATA)*(NSC+CP_LEN); // 4032
    localparam integer NBINS    = NUM_DATA * NSC;                    // 3072

    // Max vectors we size storage for (generator emits 28; allow headroom).
    localparam integer MAX_VEC  = 64;

    // Per-bin tolerance (LSB) on I and Q vs the integer-domain golden.
    // BFP truncation in the IP -> a handful of LSB. Golden bin magnitudes
    // run to a few thousand LSB so 64 is < ~1% and still catches any real
    // ordering / scale / shift / overflow bug.
    localparam integer TOL = 64;

    integer N_VEC;            // actual number of vectors (plusarg or default)

    // ---- clock / reset ----
    reg clk = 1'b0;
    always #5 clk = ~clk;
    reg rst_n = 1'b0;

    // ---- DUT wiring ----
    reg          s_valid;
    wire         s_ready;
    reg  [31:0]  s_tdata;
    wire         m_valid;
    reg          m_ready;
    wire [31:0]  m_tdata;
    wire         m_last;

    rx_fft_frontend #(
        .DATA_W(16), .NSC(256), .CP_LEN(32),
        .NUM_SYN(2), .NUM_DATA(12), .SCALE_SH(4)
    ) dut (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready), .s_tdata(s_tdata),
        .m_valid(m_valid), .m_ready(m_ready), .m_tdata(m_tdata), .m_last(m_last)
    );

    // ---- storage : all vectors concatenated ----
    reg [31:0] slot_mem [0:MAX_VEC*SLOT_LEN-1];
    reg [31:0] gold_mem [0:MAX_VEC*NBINS-1];
    reg [31:0] got_mem  [0:MAX_VEC*NBINS-1];

    initial begin
        $readmemh("golden/rx_fft_rand/slots_in.hex", slot_mem);
        $readmemh("golden/rx_fft_rand/fft_out.hex",  gold_mem);
    end

    // ---------------------------------------------------------------
    // stimulus driver : stream every vector's slot back-to-back.
    // random valid gaps ~20%. in_idx is the GLOBAL sample index across
    // all vectors (0 .. N_VEC*4032-1).
    // ---------------------------------------------------------------
    integer in_idx;
    integer total_in;
    integer vseed = 32'hBEEF1234;
    initial begin
        s_valid = 1'b0; s_tdata = 32'd0;
        rst_n   = 1'b0;
        // resolve N_VEC
        if (!$value$plusargs("N_VEC=%d", N_VEC)) N_VEC = 28;
        total_in = N_VEC * SLOT_LEN;
        repeat (8) @(posedge clk);
        rst_n   = 1'b1;
        @(posedge clk);

        in_idx = 0;
        while (in_idx < total_in) begin
            if (($random(vseed) % 5) == 0) begin
                s_valid <= 1'b0;
                @(posedge clk);
            end else begin
                s_valid <= 1'b1;
                s_tdata <= slot_mem[in_idx];
                @(posedge clk);
                if (s_valid && s_ready)
                    in_idx = in_idx + 1;
            end
        end
        s_valid <= 1'b0;
    end

    // ---- m_ready back-pressure (pseudo-random ~75% ready) ----
    integer rseed = 32'h0FACADE;
    always @(posedge clk) begin
        if (!rst_n) m_ready <= 1'b0;
        else        m_ready <= ($random(rseed) % 4) != 0;
    end

    // ---- collect output bins (global index across all vectors) ----
    integer out_cnt;
    integer total_out;
    initial begin out_cnt = 0; total_out = 28*NBINS; end
    always @(posedge clk) begin
        if (rst_n && m_valid && m_ready) begin
            if (out_cnt < MAX_VEC*NBINS) got_mem[out_cnt] <= m_tdata;
            out_cnt <= out_cnt + 1;
        end
    end

    // ---------------------------------------------------------------
    // finish + compare (per-vector, report global worst)
    // ---------------------------------------------------------------
    integer i, v, b;
    integer gi, gq, ri, rq, ei, eq;
    integer maxerr, errcnt;
    integer worst_v, worst_b;
    integer timeout;
    reg signed [15:0] gi16, gq16, ri16, rq16;

    initial begin
        timeout = 0;
        wait (rst_n);
        total_out = N_VEC * NBINS;
        while (out_cnt < total_out && timeout < 8_000_000) begin
            @(posedge clk);
            timeout = timeout + 1;
        end
        repeat (5) @(posedge clk);

        if (out_cnt < total_out) begin
            $display("FATAL: collected %0d bins, expected %0d (timeout)",
                     out_cnt, total_out);
            $display("RESULT: FAIL");
            $finish;
        end

        maxerr = 0; errcnt = 0; worst_v = -1; worst_b = -1;
        for (i = 0; i < total_out; i = i + 1) begin
            v = i / NBINS;
            b = i % NBINS;
            gi16 = gold_mem[i][15:0];   gq16 = gold_mem[i][31:16];
            ri16 = got_mem[i][15:0];    rq16 = got_mem[i][31:16];
            gi = gi16; gq = gq16; ri = ri16; rq = rq16;
            ei = (ri > gi) ? (ri - gi) : (gi - ri);
            eq = (rq > gq) ? (rq - gq) : (gq - rq);
            if (ei > maxerr) begin maxerr = ei; worst_v = v; worst_b = b; end
            if (eq > maxerr) begin maxerr = eq; worst_v = v; worst_b = b; end
            if (ei > TOL || eq > TOL) begin
                errcnt = errcnt + 1;
                if (errcnt <= 12)
                    $display("  MISMATCH vec %0d sym %0d k %0d: got(%0d,%0d) gold(%0d,%0d) err(%0d,%0d)",
                             v, b/NSC, b%NSC, ri, rq, gi, gq, ei, eq);
            end
        end

        $display("==================================================");
        $display(" rx_fft_frontend RANDOMIZED multi-vector self-check");
        $display("   vectors            = %0d", N_VEC);
        $display("   bins collected     = %0d / %0d", out_cnt, total_out);
        $display("   per-bin tol (LSB)  = %0d", TOL);
        $display("   max abs err (LSB)  = %0d  (vec %0d, sym %0d, k %0d)",
                 maxerr, worst_v, worst_b/NSC, worst_b%NSC);
        $display("   bins over tol      = %0d", errcnt);
        if (out_cnt == total_out && errcnt == 0)
            $display("RESULT: PASS  (all %0d vectors x %0d bins within %0d LSB, max err %0d)",
                     N_VEC, NBINS, TOL, maxerr);
        else
            $display("RESULT: FAIL  (%0d bins exceed tol, max err %0d at vec %0d)",
                     errcnt, maxerr, worst_v);
        $display("==================================================");
        $finish;
    end

    // global watchdog
    initial begin
        #200_000_000;
        $display("FATAL: global timeout");
        $display("RESULT: FAIL");
        $finish;
    end

endmodule

`default_nettype wire
